              'icon': [
                {'width': '18px'},
                {'color': 'var(--secondary-text-color)'}
              ],
              'name': [
                {'justify-self': 'start'},
                {'font-size': '13px'},
                {'font-weight': '600'},
                {'color': 'var(--secondary-text-color)'}
