          {%- if progress_pct < 0 -%}{%- set progress_pct = 0 -%}{%- endif -%}
          {%- if progress_pct > 100 -%}{%- set progress_pct = 100 -%}{%- endif -%}
          {%- set progress_display = ('%.0f' | format(progress_pct)) -%}
          {%- set progress_html = "<div style='margin-top:2px;padding:8px 10px;border-radius:8px;background:var(--secondary-background-color);border:1px solid var(--divider-color);'><div style='display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:11px;'><span><ha-icon icon='mdi:trophy' style='width:14px;height:14px;color:" ~ status_color ~ ";transform:translateY(-1px);'></ha-icon> " ~ ui.get('progress', 'err-progress') ~ "</span><span style='font-weight:600;'>" ~ ((achievement.progress_clamped | round(2)) | string | regex_replace('\.?0+$', '')) ~ "/" ~ ((achievement.target_value | round(2)) | string | regex_replace('\.?0+$', '')) ~ "</span></div><div style='margin-top:6px;display:flex;align-items:center;gap:6px;'><div style='flex:1;height:6px;background:var(--divider-color);border-radius:999px;overflow:hidden;'><div style='width:" ~ progress_display ~ "%;height:100%;background:" ~ status_color ~ ";border-radius:999px;'></div></div><span style='font-size:10px;color:var(--secondary-text-color);line-height:1;'>" ~ progress_display ~ "%</span></div></div>" -%}
        {%- endif -%}

