{%- elif pref_primary_tint_mix_pct > 100 -%}
  {%- set pref_primary_tint_mix_pct = 100 -%}
{%- endif -%}

{%- set fallback_name = 'Wystan' -%}
{%- set name = fallback_name -%}
{%- set user_id = '4087982b-c8fd-40ba-a365-3a8ff4512658' -%}
{%- set entry_id = '01KXV33Q540SYEF1KFM54DCEDJ' -%}
{%- set lookup_key = entry_id ~ ':' ~ user_id -%}
{%- if not (use_override_dashboard_helper | default(false, true)) -%}
  {%- set dashboard_helper = integration_entities('choreops')
      | select('search', '^sensor\\.')
      | list
      | expand
      | selectattr('attributes.purpose', 'defined')
      | selectattr('attributes.purpose', 'eq', 'purpose_dashboard_helper')
      | selectattr('attributes.dashboard_lookup_key', 'eq', lookup_key)
      | map(attribute='entity_id')
      | first
      | default("err-dashboard_helper_missing", true) -%}
{%- endif -%}
{%- set resolved_name = (state_attr(dashboard_helper, 'user_name') if dashboard_helper not in ['err-dashboard_helper_missing', '', None] else '') | default('', true) -%}
{%- if resolved_name != '' -%}
  {%- set name = resolved_name -%}
{%- endif -%}

{#-- Validation: Check if user context is configured --#}
{%- if name == '' -%}
  {{
    {
      'type': 'markdown',
