  {%- set skip_render = true -%}
{%- else -%}
  {%- set skip_render = false -%}
{%- endif -%}

{%- if not skip_render -%}

  {#-- 3. Initialize --#}
  {%- set ns = namespace(
    badges=[],
    points_earned_all_time=0,
    points_label='Points',
    m_frequency='',
    m_status='active',
    m_cycle_pts=0,
    m_end_date='',
