    {%- set selected_dashboard_helper = state_attr(admin_selector_eid, 'dashboard_helper_eid') if has_selected_user and admin_selector_eid not in ['', None] else '' -%}
    {%- set selected_helper_matches = helper_sensor_entities | selectattr('attributes.user_name', 'eq', selected_user_name) | list if has_selected_user else [] -%}
    {%- if selected_dashboard_helper in ['', None, 'None'] and selected_helper_matches | count > 0 -%}
      {%- set selected_dashboard_helper = selected_helper_matches[0].entity_id -%}
    {%- endif -%}
    {%- set has_selected_dashboard_helper = selected_dashboard_helper not in ['', None, 'None'] and states(selected_dashboard_helper) not in ['unknown', 'unavailable'] -%}
    {%- set selected_user_id = state_attr(selected_dashboard_helper, 'user_id') if has_selected_dashboard_helper else '' -%}
    {%- set selected_user_ui_control = state_attr(selected_dashboard_helper, 'ui_control') | default({}, true) if has_selected_dashboard_helper else {} -%}
    {%- set ui_root = namespace(
      shared_admin=shared_admin_ui_control if shared_admin_ui_control is mapping else {},
      selected_user=selected_user_ui_control if selected_user_ui_control is mapping else {}
    ) -%}

{%- if admin_selector_eid == '' or shared_admin_helper_eid == '' -%}
      {{
        {
          'type': 'markdown',
          'content': "⚠️ **Admin Dashboard Helpers Not Found**\n\nThe admin selector or shared admin helper entity could not be resolved for this dashboard context."
        }
      }},
      {%- set skip_render = true -%}
    {%- else -%}
      {%- set skip_render = false -%}
    {%- endif -%}

{%- set pref_economy_management_ui_control_key_root = (pref_economy_management_ui_control_key_root | default('admin-shared/economy-management') | string) -%}
{%- set pref_economy_management_ui_control_key_root_segments = pref_economy_management_ui_control_key_root.split('/') | reject('equalto', '') | list -%}
{%- if pref_economy_management_ui_control_key_root_segments | length == 0 -%}
  {%- set pref_economy_management_ui_control_key_root_segments = ['admin-shared', 'economy-management'] -%}
{%- endif -%}
{%- set pref_economy_management_ui_control_key_root = pref_economy_management_ui_control_key_root_segments | join('/') -%}
{%- set pref_economy_management_default_header_collapsed = (pref_economy_management_default_header_collapsed | default('true') | string | lower) == 'true' -%}
{%- set pref_economy_management_primary_tint_mix_pct = pref_economy_management_primary_tint_mix_pct | int(default=14) -%}
{%- set pref_economy_management_show_header_background = (pref_economy_management_show_header_background | default('true') | string | lower) == 'true' -%}
{%- set pref_economy_management_show_header_thin_border = (pref_economy_management_show_header_thin_border | default('true') | string | lower) == 'true' -%}
{%- set pref_points_precision = pref_points_precision | default('fixed_0') | string | lower -%}
{%- if pref_points_precision not in ['fixed_0', 'adaptive', 'fixed_1', 'fixed_2'] -%}
  {%- set pref_points_precision = 'fixed_0' -%}
{%- endif -%}
{%- if pref_economy_management_primary_tint_mix_pct < 0 -%}
  {%- set pref_economy_management_primary_tint_mix_pct = 0 -%}
{%- elif pref_economy_management_primary_tint_mix_pct > 100 -%}
  {%- set pref_economy_management_primary_tint_mix_pct = 100 -%}
{%- endif -%}

{%- if not skip_render -%}

  {#-- 3. Initialize Variables --#}

  {%- set ui = shared_admin_ui -%}
  {%- if summary_helper in ['', None, 'None'] -%}
    {{ {
      'type': 'markdown',
      'content': "⚠️ **Dashboard configuration error**\n\nCannot find any dashboard helper entities for this shared admin view.\n\nCheck Settings → Integrations → ChoreOps and verify at least one user is configured."
    } }},
    {%- set skip_render = true -%}
  {%- endif -%}
{%- endif -%}

{%- if not skip_render -%}

  {#-- 4. Collect Data --#}

  {%- set integration_entry_id = state_attr(shared_admin_helper_eid, 'integration_entry_id') if shared_admin_helper_eid not in ['', None, 'None'] else '' -%}
  {%- set ui_control_key_root = pref_economy_management_ui_control_key_root -%}
  {%- set ui_control_key_header_collapsed = ui_control_key_root ~ '/header-collapse' -%}
  {%- set selected_user_ui_root = namespace(current=ui_root.selected_user if ui_root.selected_user is mapping else {}) -%}
  {%- for segment in ui_control_key_root.split('/') -%}
    {%- if selected_user_ui_root.current is mapping -%}
      {%- set selected_user_ui_root.current = selected_user_ui_root.current.get(segment, {}) -%}
    {%- else -%}
      {%- set selected_user_ui_root.current = {} -%}
    {%- endif -%}
  {%- endfor -%}
  {%- set has_header_collapsed_override = selected_user_ui_root.current is mapping and 'header-collapse' in selected_user_ui_root.current -%}
  {%- set selected_dashboard_helpers = state_attr(selected_dashboard_helper, 'dashboard_helpers') or {} if has_selected_dashboard_helper else {} -%}
  {%- set selected_core_sensors = state_attr(selected_dashboard_helper, 'core_sensors') or {} if has_selected_dashboard_helper else {} -%}
  {%- set points_sensor = selected_core_sensors.get('points_eid') if has_selected_dashboard_helper else '' -%}
  {%- set selected_gamification_enabled = state_attr(selected_dashboard_helper, 'gamification_enabled') | default(false, true) if has_selected_dashboard_helper else false -%}
  {%- set point_buttons = state_attr(selected_dashboard_helper, 'points_buttons') | default([], true) if has_selected_dashboard_helper else [] -%}
  {%- set bonus_list = state_attr(selected_dashboard_helper, 'bonuses') | default([], true) if has_selected_dashboard_helper else [] -%}
  {%- set penalty_list = state_attr(selected_dashboard_helper, 'penalties') | default([], true) if has_selected_dashboard_helper else [] -%}
  {%- set has_points_sensor = points_sensor not in ['', None, 'None'] and states(points_sensor) not in ['unknown', 'unavailable'] -%}
  {%- set points_label = (state_attr(points_sensor, 'unit_of_measurement') if has_points_sensor else None) or 'Points' -%}
  {%- set points_icon = (state_attr(points_sensor, 'icon') if has_points_sensor else None) or 'mdi:star-outline' -%}
  {%- set points_total_display = states(points_sensor) if has_points_sensor and states(points_sensor) not in ['unknown', 'unavailable', 'None', ''] else '0' -%}
  {%- set header_collapsed = selected_user_ui_root.current['header-collapse'] if has_header_collapsed_override else pref_economy_management_default_header_collapsed -%}
  {%- set header_collapsed = (header_collapsed | string | lower) == 'true' -%}
  {%- set economy_label = ui.get('manage_for', 'Manage for') if has_selected_user else ui.get('select_user_first', 'err-select_user_first') -%}
  {%- set economy_label_html = (
    "<span style='color:var(--secondary-text-color);'>" ~ ui.get('manage_for', 'Manage for') ~ ":</span> <span style='font-weight:700;color:var(--primary-text-color);'>" ~ (selected_user_name | e) ~ "</span>"
    if has_selected_user
    else economy_label
  ) -%}
  {%- set points_total_numeric = points_total_display | float(default=0) -%}
  {%- set points_total_numeric = points_total_numeric | round(2) -%}
  {%- set points_total_compact = (points_total_numeric | int) | string if pref_points_precision == 'adaptive' and points_total_numeric == (points_total_numeric | int) else ('%.1f' | format(points_total_numeric) if pref_points_precision == 'fixed_1' else ('%.2f' | format(points_total_numeric) if pref_points_precision == 'fixed_2' else ((points_total_numeric | round(0) | int) | string if pref_points_precision != 'adaptive' else ('%.1f' | format(points_total_numeric) if points_total_numeric == (points_total_numeric | round(1)) else '%.2f' | format(points_total_numeric))))) -%}
  {%- set points_multiplier = (state_attr(points_sensor, 'points_multiplier') | float(default=1)) if has_points_sensor else 1 -%}
  {%- set points_multiplier_text = (points_multiplier | round(2)) | string -%}
  {%- set points_week_earned = (state_attr(points_sensor, 'point_stat_points_earned_week') | float(default=0)) if has_points_sensor else 0 -%}
  {%- set points_week_earned_text = ((points_week_earned | round(2)) | string | regex_replace('\.?0+$', '')) if pref_points_precision != 'fixed_0' else (points_week_earned | round(0) | int) | string -%}
  {%- set points_avg_per_day_week = (state_attr(points_sensor, 'point_stat_avg_points_per_day_week') | float(default=0)) if has_points_sensor else 0 -%}
  {%- set points_avg_per_day_text = ((points_avg_per_day_week | round(2)) | string | regex_replace('\.?0+$', '')) if pref_points_precision != 'fixed_0' else (points_avg_per_day_week | round(0) | int) | string -%}
    {%- set points_by_source_all_time = (state_attr(points_sensor, 'point_stat_points_by_source_all_time') if has_points_sensor else {}) or {} -%}
    {%- set bonus_points_all_time = (points_by_source_all_time.get('bonuses', 0) | float(default=0)) if points_by_source_all_time is mapping else 0 -%}
    {%- set penalty_points_all_time = (points_by_source_all_time.get('penalties', 0) | float(default=0)) if points_by_source_all_time is mapping else 0 -%}
  {%- set bonus_points_all_time_text = ((bonus_points_all_time | abs | round(2)) | string | regex_replace('\.?0+$', '')) if pref_points_precision != 'fixed_0' else ((bonus_points_all_time | abs) | round(0) | int) | string -%}
  {%- set penalty_points_all_time_text = ((penalty_points_all_time | abs | round(2)) | string | regex_replace('\.?0+$', '')) if pref_points_precision != 'fixed_0' else ((penalty_points_all_time | abs) | round(0) | int) | string -%}
  {%- set button_grid_columns = 6 -%}
  {%- set bonus_ns = namespace(rows_html='', top_count=0, total_points=0, total_applied=0) -%}
  {%- for bonus in bonus_list | sort(attribute='applied', reverse=true) -%}
    {%- if bonus is mapping -%}
      {%- set bonus_applied = bonus.get('applied', 0) | int(default=0) -%}
      {%- set bonus_points = bonus.get('points', 0) | float(default=0) -%}
      {%- if bonus_applied > 0 -%}
        {%- set bonus_ns.total_applied = bonus_ns.total_applied + bonus_applied -%}
        {%- set bonus_ns.total_points = bonus_ns.total_points + (bonus_points * bonus_applied) -%}
      {%- endif -%}
      {%- if bonus_ns.top_count < 3 -%}
        {%- set bonus_name = ((bonus.get('name') or ui.get('bonus', 'err-bonus')) | string | trim) -%}
        {%- set bonus_name_safe = bonus_name | replace('&', '&amp;') | replace('<', '&lt;') | replace('>', '&gt;') -%}
        {%- set bonus_button_eid = bonus.get('eid') if bonus is mapping else none -%}
        {%- set bonus_icon = (state_attr(bonus_button_eid, 'icon') if bonus_button_eid else none) | default('mdi:gift-outline', true) -%}
        {%- set bonus_applied_label = (" x" ~ bonus_applied|string) if bonus_applied > 0 else '' -%}
        {%- set bonus_ns.top_count = bonus_ns.top_count + 1 -%}
        {%- set bonus_ns.rows_html = bonus_ns.rows_html ~ "<div style='display:grid;grid-template-columns:18px minmax(0,1fr) auto;column-gap:8px;align-items:center;padding:5px 0;'><span style='width:18px;height:18px;display:flex;align-items:center;justify-content:center;'><ha-icon icon='" ~ bonus_icon ~ "' style='width:14px;height:14px;color:var(--success-color);transform:translateY(-3px);'></ha-icon></span><div style='min-width:0;font-size:12px;font-weight:600;color:var(--primary-text-color);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;'>" ~ bonus_name_safe ~ "</div><div style='display:flex;align-items:center;gap:6px;font-size:10px;font-weight:700;white-space:nowrap;'><span style='color:var(--success-color);'>+" ~ (((bonus_points | round(2)) | string | regex_replace('\.?0+$', ''))) ~ "</span><span style='color:var(--secondary-text-color);'>" ~ (bonus_applied_label if bonus_applied_label | length > 0 else '•') ~ "</span></div></div>" -%}
      {%- endif -%}
    {%- endif -%}
  {%- endfor -%}
  {%- set penalty_ns = namespace(rows_html='', top_count=0, total_points=0, total_applied=0) -%}
  {%- for penalty in penalty_list | sort(attribute='applied', reverse=true) -%}
    {%- if penalty is mapping -%}
      {%- set penalty_applied = penalty.get('applied', 0) | int(default=0) -%}
      {%- set penalty_points = penalty.get('points', 0) | float(default=0) -%}
      {%- if penalty_applied > 0 -%}
        {%- set penalty_ns.total_applied = penalty_ns.total_applied + penalty_applied -%}
        {%- set penalty_ns.total_points = penalty_ns.total_points + (penalty_points * penalty_applied) -%}
      {%- endif -%}
      {%- if penalty_ns.top_count < 3 -%}
        {%- set penalty_name = ((penalty.get('name') or ui.get('penalty', 'err-penalty')) | string | trim) -%}
        {%- set penalty_name_safe = penalty_name | replace('&', '&amp;') | replace('<', '&lt;') | replace('>', '&gt;') -%}
        {%- set penalty_button_eid = penalty.get('eid') if penalty is mapping else none -%}
        {%- set penalty_icon = (state_attr(penalty_button_eid, 'icon') if penalty_button_eid else none) | default('mdi:alert-octagon-outline', true) -%}
        {%- set penalty_applied_label = (" x" ~ penalty_applied|string) if penalty_applied > 0 else '' -%}
        {%- set penalty_ns.top_count = penalty_ns.top_count + 1 -%}
        {%- set penalty_ns.rows_html = penalty_ns.rows_html ~ "<div style='display:grid;grid-template-columns:18px minmax(0,1fr) auto;column-gap:8px;align-items:center;padding:5px 0;'><span style='width:18px;height:18px;display:flex;align-items:center;justify-content:center;'><ha-icon icon='" ~ penalty_icon ~ "' style='width:14px;height:14px;color:var(--error-color);transform:translateY(-3px);'></ha-icon></span><div style='min-width:0;font-size:12px;font-weight:600;color:var(--primary-text-color);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;'>" ~ penalty_name_safe ~ "</div><div style='display:flex;align-items:center;gap:6px;font-size:10px;font-weight:700;white-space:nowrap;'><span style='color:var(--error-color);'>" ~ (((penalty_points | round(2)) | string | regex_replace('\.?0+$', ''))) ~ "</span><span style='color:var(--secondary-text-color);'>" ~ (penalty_applied_label if penalty_applied_label | length > 0 else '•') ~ "</span></div></div>" -%}
      {%- endif -%}
    {%- endif -%}
  {%- endfor -%}
  {%- set bonus_total_points_text = ((bonus_ns.total_points | abs | round(2)) | string | regex_replace('\.?0+$', '')) if pref_points_precision != 'fixed_0' else ((bonus_ns.total_points | abs) | round(0) | int) | string -%}
  {%- set penalty_total_points_text = ((penalty_ns.total_points | abs | round(2)) | string | regex_replace('\.?0+$', '')) if pref_points_precision != 'fixed_0' else ((penalty_ns.total_points | abs) | round(0) | int) | string -%}
  {%- set points_per_day_compact = (ui.get('points_per_day', 'Points / Day') | replace(' / ', '/') | replace(' /', '/') | replace('/ ', '/')) -%}
  {%- set hero_metrics_html = "<div style='display:flex;flex-wrap:wrap;gap:8px;margin-top:12px;'><span style='display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;background:color-mix(in srgb, var(--primary-color) 10%, var(--card-background-color));font-size:11px;font-weight:700;color:var(--primary-text-color);'>⚡ x" ~ points_multiplier_text ~ " " ~ ui.get('active', 'err-active') ~ "</span><span style='display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;background:color-mix(in srgb, var(--success-color) 8%, var(--card-background-color));font-size:11px;font-weight:700;color:var(--primary-text-color);'>📅 +" ~ points_week_earned_text ~ " " ~ ui.get('this_week', 'This Week') ~ "</span><span style='display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;background:color-mix(in srgb, var(--warning-color) 9%, var(--card-background-color));font-size:11px;font-weight:700;color:var(--primary-text-color);'>📈 " ~ points_avg_per_day_text ~ " " ~ points_per_day_compact ~ "</span></div>" -%}
  {%- set points_hero_card = {
    'type': 'custom:button-card',
    'entity': points_sensor if has_points_sensor else selected_dashboard_helper,
    'show_name': False,
    'show_label': False,
    'show_state': False,
    'show_icon': False,
    'tap_action': ({
      'action': 'more-info',
      'entity': points_sensor
    } if has_points_sensor else {'action': 'none'}),
    'hold_action': ({
      'action': 'more-info',
      'entity': points_sensor
    } if has_points_sensor else {'action': 'none'}),
    'custom_fields': {
      'content': "<div style='display:flex;flex-direction:column;gap:0;'><div style='display:flex;align-items:flex-start;justify-content:space-between;gap:14px;'><div style='min-width:0;'><div style='font-size:11px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:var(--secondary-text-color);'>" ~ ui.get('available', 'err-available') ~ "</div><div style='margin-top:6px;font-size:30px;font-weight:800;line-height:1;color:var(--primary-text-color);'>" ~ points_total_compact ~ "</div><div style='margin-top:5px;font-size:13px;font-weight:600;color:var(--secondary-text-color);'>" ~ points_label ~ "</div>" ~ hero_metrics_html ~ "</div><div style='display:flex;align-items:center;justify-content:center;flex:0 0 auto;'><ha-icon icon='" ~ points_icon ~ "' style='width:30px;height:30px;color:var(--primary-color);'></ha-icon></div></div></div>"
    },
    'styles': {
      'card': [
        {'padding': '0'},
        {'border-radius': '0'},
        {'box-shadow': 'none'},
        {'border': 'none'},
        {'background': 'transparent'}
      ],
      'grid': [
        {'grid-template-areas': '"content"'},
        {'grid-template-columns': '1fr'}
      ],
      'custom_fields': {
        'content': [
          {'justify-self': 'stretch'},
          {'width': '100%'},
          {'text-align': 'left'}
        ]
      }
    }
  } -%}
  {%- set points_button_cards = namespace(items=[]) -%}
  {%- for button_data in point_buttons -%}
    {%- set button_eid = button_data.eid if button_data is mapping else button_data -%}
    {%- set button_name = button_data.name if button_data is mapping else '' -%}
    {%- set button_name_short = button_name[7:] if button_name[:7] == 'Points ' else button_name -%}
    {%- set button_icon = (state_attr(button_eid, 'icon') if button_eid else none) | default('mdi:star-four-points-outline', true) -%}
    {%- set button_delta_value = button_name_short | float(default=0) -%}
    {%- set button_delta_abs = ((button_delta_value | abs | round(2)) | string | regex_replace('\.?0+$', '')) if pref_points_precision != 'fixed_0' else (button_delta_value | abs | round(0) | int) | string -%}
    {%- set button_name_display = ('+' ~ button_delta_abs) if button_delta_value > 0 else ('-' ~ button_delta_abs) if button_delta_value < 0 else button_name_short -%}
    {%- set is_positive = button_delta_value > 0 -%}
    {%- set button_card = {
      'type': 'custom:button-card',
      'entity': button_eid,
      'show_icon': True,
      'show_name': True,
      'show_label': False,
      'show_state': False,
      'icon': button_icon,
      'name': button_name_display if button_name_display not in ['', none] else button_name,
      'tap_action': {
        'action': 'call-service',
        'service': 'button.press',
        'data': {'entity_id': button_eid}
      } if button_eid not in ['', none] else {'action': 'none'},
      'hold_action': {'action': 'more-info'} if button_eid not in ['', none] else {'action': 'none'},
      'styles': {
        'card': [
          {'padding': '8px 4px'},
          {'border-radius': '12px'},
          {'box-shadow': 'none'},
          {'border': ('1px solid color-mix(in srgb, var(--success-color) 22%, var(--divider-color))') if is_positive else ('1px solid color-mix(in srgb, var(--error-color) 22%, var(--divider-color))')},
          {'background': ('color-mix(in srgb, var(--success-color) 8%, var(--card-background-color))') if is_positive else ('color-mix(in srgb, var(--error-color) 7%, var(--card-background-color))')}
        ],
        'grid': [
          {'grid-template-areas': '"i" "n"'},
          {'grid-template-columns': '1fr'},
          {'row-gap': '4px'}
        ],
        'icon': [
          {'width': '16px'},
          {'color': 'var(--success-color)' if is_positive else 'var(--error-color)'}
        ],
        'name': [
          {'font-size': '11px'},
          {'font-weight': '700'},
          {'line-height': '1.2'},
          {'color': 'var(--primary-text-color)'}
        ]
      }
    } -%}
    {%- set points_button_cards.items = points_button_cards.items + [button_card] -%}
  {%- endfor -%}
  {%- set points_buttons_grid_card = {
    'type': 'grid',
    'columns': button_grid_columns,
    'square': False,
    'cards': points_button_cards.items
  } -%}
  {%- set bonus_action_cards = namespace(items=[]) -%}
  {%- for bonus in bonus_list -%}
    {%- if bonus is mapping -%}
      {%- set bonus_eid = bonus.get('eid') -%}
      {%- set bonus_name = (bonus.get('name') or ui.get('bonus', 'err-bonus')) | string -%}
      {%- set bonus_points = bonus.get('points', 0) | float(default=0) -%}
      {%- set bonus_applied = bonus.get('applied', 0) | int(default=0) -%}
      {%- set bonus_points_display = ((bonus_points | abs | round(2)) | string | regex_replace('\.?0+$', '')) if pref_points_precision != 'fixed_0' else ((bonus_points | abs) | round(0) | int) | string -%}
      {%- set bonus_icon = (state_attr(bonus_eid, 'icon') if bonus_eid else none) | default('mdi:gift-outline', true) -%}
      {%- set bonus_action_cards.items = bonus_action_cards.items + [{
        'type': 'custom:button-card',
        'entity': bonus_eid if bonus_eid not in ['', none] else selected_dashboard_helper,
        'show_icon': False,
        'show_name': False,
        'show_label': False,
        'show_state': False,
        'tap_action': {'action': 'none'},
        'hold_action': {'action': 'more-info'} if bonus_eid not in ['', none] else {'action': 'none'},
        'custom_fields': {
          'kind': "<div style='width:28px;height:28px;border-radius:10px;display:flex;align-items:center;justify-content:center;background:color-mix(in srgb, var(--success-color) 10%, transparent);border:1px solid color-mix(in srgb, var(--success-color) 22%, var(--divider-color));'><ha-icon icon='" ~ bonus_icon ~ "' style='width:16px;height:16px;color:var(--success-color);transform:translateY(-3px);'></ha-icon></div>",
          'title': bonus_name,
          'meta': '+' ~ bonus_points_display ~ (' • ' ~ bonus_applied|string ~ ' ' ~ ui.get('applied', 'err-applied') if bonus_applied > 0 else ''),
          'btn_clear': {
